    z, multiplier = 0j, 1+0j
    out = [(0, z, multiplier)]
    for k in range(1, steps + 1):
        multiplier *= 2*z
        z = z*z + c
        out.append((k, z, multiplier))
    return out

for parameter, steps in [(0j, 1), (-1+0j, 2)]:
