    count, p, remaining = 0, 2, n
    while p*p <= remaining:
        if remaining % p == 0:
            remaining //= p; count += 1
            if remaining % p == 0: return 0
            while remaining % p == 0: remaining //= p
        p += 1
    if remaining > 1: count += 1
    return -1 if count % 2 else 1

